krb5_error_code prepare_kdc_request_for_reprocessing(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;

    if ((request->flags & KDC_OPT_CANONICALIZE) && krbtgt_princ) {
        krb5_principal server_princ = NULL;
        char *realm = NULL;

        ret = krb5_unparse_name(request->context, *krbtgt_princ, &server_princ);
        if (ret != 0) {
            return ret;
        }

        if (krb5_is_fqdn_in_principal(request->context, server_princ)) {
            ret = krb5_map_fqdn_to_realm(request->context, server_princ, &realm);
            if (ret != 0) {
                krb5_free_unparsed_name(request->context, server_princ);
                return ret;
            }

            request->client = NULL;
            request->server = *krbtgt_princ;
            request->flags |= KDC_OPT_CROSS_REALM;

            free(realm);
        }

        krb5_free_unparsed_name(request->context, server_princ);
    }

    return ret;
}

krb5_error_code prepare_kdc_request_for_reprocessing(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code retval = 0;
    krb5_context context = NULL;
    krb5_principal server_princ = NULL;
    krb5_data *realm = NULL;

    if (!request || !krbtgt_princ) {
        return KRB5KDC_ERR_BADOPTION;
    }

    if (request->kdc_options & KDC_OPT_CANONICALIZE) {
        server_princ = request->client;

        /* Assume a helper function exists to extract FQDN and map it to a realm */
        realm = extract_fqdn_and_map_to_realm(server_princ);
        if (!realm) {
            retval = KRB5_REALM_CANT_RESOLVE;
            goto cleanup;
        }

        /* Modify the request to construct a cross-realm TGT */
        if (krb5_build_principal(context, krbtgt_princ, 1, realm, NULL) != 0) {
            retval = KRB5KDC_ERR_INVALID_SERVER;
            goto cleanup;
        }

        /* Modify the KDC request as necessary */
        request->kdc_options &= ~KDC_OPT_CANONICALIZE;
    }

cleanup:
    if (context != NULL) {
        krb5_free_context(context);
    }
    if (realm != NULL) {
        krb5_free_data(context, realm);
    }

    return retval;
}

krb5_error_code prepare_reprocessed_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;
    krb5_principal server_princ = NULL;
    krb5_data *realm = NULL;

    if ((request->kdc_options & KDC_OPT_CANONICALIZE) == 0) {
        return 0;
    }

    server_princ = request->client;

    if (!server_princ || krb5_principal_is_NULL(server_princ)) {
        return KRB5KDC_ERR_BAD_CLIENT;
    }

    /* Assume server_princ is a FQDN and try to map to realm */
    ret = krb5_kuserok_realm_from_fqdn(request->context, server_princ, &realm);
    if (ret != 0) {
        return ret;
    }

    if (!realm) {
        return KRB5_KDC_NO_REALM_MAPPING;
    }

    /* Modify the request to construct a cross-realm TGT */
    ret = krb5_build_cross_realm_tgt(request, realm, krbtgt_princ);
    if (ret != 0) {
        krb5_free_data(request->context, realm);
        return ret;
    }

    krb5_free_data(request->context, realm);
    return 0;
}

krb5_error_code prepare_and_modify_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code ret = 0;

    if (request->flags & KRB5_KDCREQ_CANONICALIZE) {
        const char *server_name = krb5_principal_get_server_name(*krbtgt_princ);
        if (server_name && is_valid_fqdn(server_name)) {
            char *realm = NULL;
            ret = map_fqdn_to_realm(server_name, &realm);
            if (ret != 0) {
                return ret;
            }

            krb5_data *new_realm_data = krb5_data_copy(realm);
            if (!new_realm_data) {
                free(realm);
                return ENOMEM;
            }

            ret = modify_request_for_cross_realm(request, new_realm_data);
            if (ret != 0) {
                krb5_data_free(new_realm_data);
                free(realm);
                return ret;
            }

            free(realm);
        }
    }

    return ret;
}

krb5_error_code prepare_reprocess_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_error_code code = 0;
    krb5_boolean canonicalize = (request->kdc_options & KDC_OPT_CANONICALIZE) ? TRUE : FALSE;

    if (canonicalize) {
        krb5_principal server_princ = NULL;
        code = krb5_copy_principal(request->context, *krbtgt_princ, &server_princ);
        if (code != 0) {
            return code;
        }

        char *fqdn = NULL;
        code = krb5_unparse_name(request->context, server_princ, &fqdn);
        if (code != 0) {
            krb5_free_principal(request->context, server_princ);
            return code;
        }

        char *realm = NULL;
        code = krb5_get_realm_from_fqdn(request->context, fqdn, &realm);
        if (code != 0) {
            krb5_free_unparsed_name(request->context, fqdn);
            krb5_free_principal(request->context, server_princ);
            return code;
        }

        krb5_principal cross_realm_tgt = NULL;
        code = krb5_build_principal(request->context, &cross_realm_tgt,
                                    strlen(realm), realm,
                                    strlen("krbtgt"), "krbtgt",
                                    strlen(fqdn), fqdn,
                                    0);
        if (code != 0) {
            krb5_free_realm(request->context, realm);
            krb5_free_unparsed_name(request->context, fqdn);
            krb5_free_principal(request->context, server_princ);
            return code;
        }

        request->client = cross_realm_tgt;

        krb5_free_realm(request->context, realm);
        krb5_free_unparsed_name(request->context, fqdn);
        krb5_free_principal(request->context, server_princ);
    }

    return code;
}
